#!/usr/bin/env python
"""Generates README.md from the files in this directory (JSONs, manifests, section*_output.txt) and PREREGISTRATION.md.
Every count in the tables is computed here from the JSONs; the verbatim blocks are the section*_output.txt files."""
import collections, hashlib, json, math, subprocess, sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent))
import run_section3 as S
EV = Path(__file__).resolve().parent; REPO = EV.parents[2]; PRE = EV.parent / "PREREGISTRATION.md"
NAMES = [f"rs31{a}_seed{i}" for a in "CD" for i in range(2)]
PAIRS = S.PAIRS24
def wilson(k, n, z=1.96):
    p = k / n; d = 1 + z * z / n; c = (p + z * z / (2 * n)) / d; h = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / d
    return max(0.0, 100 * (c - h)), min(100.0, 100 * (c + h))
W = lambda k, n: f"{k}/{n} = {100*k/n:.1f}% [{wilson(k,n)[0]:.1f}, {wilson(k,n)[1]:.1f}]"
def table(head, rows):
    return "\n".join(["| " + " | ".join(head) + " |", "|" + "|".join("---" for _ in head) + "|"] + ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]) + "\n"
def J(f): return json.load(open(EV / f))
def sha(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def block(f): return "```\n" + (EV / f).read_text().rstrip("\n") + "\n```\n"
def episodes(f, pairs):
    d = J(f); k, n = collections.Counter(), collections.Counter()
    for e in d["episodes"]: p = f'{e["start_square"]}:{e["target_square"]}'; n[p] += 1; k[p] += e["place"]["placed"]
    E = d["episodes"]
    fun = dict(g=sum(e["grasp_ever"] for e in E), h=sum(e["place"]["held"] for e in E), r=sum(e["place"]["released"] for e in E), p=sum(k.values()))
    return d, k, n, fun, collections.Counter(e["reason"] for e in E)
M2 = J("EVAL_MANIFEST.json"); M3 = J("EVAL_MANIFEST_section3.json")
git = lambda *a: subprocess.run(["git", *a], cwd=REPO, capture_output=True, text=True, check=True).stdout.strip()
out = []; A = out.append

A("# RS31: PPO on 24 start squares, entropy bonus 0.01: evaluation\n")
A(f"Generated by `make_readme.py` from the JSONs, manifests and `section*_output.txt` in this directory. Worktree SHA `{M2['git_start']['head']}` (branch `{M2['git_start']['branch']}`); tracked-dirty files at start and end of the evaluations: {M2['git_start']['tracked_dirty_count']} and {M2['git_end']['tracked_dirty_count']}. Wilson 95% intervals throughout: z = 1.96, no continuity correction. No verdict is written here: only numbers and the mechanical rule table.\n")

A("## 1. Protocol (pre-registered)\n")
A(f"Quoted, not paraphrased, from `results/rs31_24_pairs/PREREGISTRATION.md`: sha256 `{sha(PRE)}`, git blob `{git('hash-object', str(PRE))}`, last commit touching it `{git('log', '-1', '--format=%H', '--', str(PRE.relative_to(REPO)))}`.\n")
A("```\n" + PRE.read_text().rstrip("\n") + "\n```\n")
rule4 = [l for l in PRE.read_text().splitlines() if l.startswith("4. ")][0]
A(f"Rule 4 text, verbatim from that file: `{rule4}`\n")
A("Evaluation command per model (see `EVAL_MANIFEST.json` for the exact string): `scripts/eval_probe.py <run> --episodes 1200 --pairs <24 pairs in the preregistered order> --seed 20000` (stochastic, `final_model.zip` with `final_vecnormalize.pkl`), run through `rms_wrapper.py` (deviation h).\n")

A("## 2. Models and file hashes\n")
rows = []
for nm in NAMES:
    e = [x for x in M2["evals"] if x["label"] == nm][0]; r = e["run"]
    rows.append([f"`{r}`", f"`{e['model_sha256']}`", f"`{e['vecnormalize_sha256']}`", f"`{e['output_json_sha256']}`"])
A(table(["run", "final_model.zip sha256", "final_vecnormalize.pkl sha256", f"{{model}}_final.json sha256"], rows))
A(f"`scripts/eval_probe.py` sha256 `{M2['sha256']['scripts/eval_probe.py']}`. Hashes of every other output JSON are in `EVAL_MANIFEST.json` (Section 2) and `EVAL_MANIFEST_section3.json` (reported items).\n")

# ---------------- gated
A("## 3. GATED results (PREREGISTRATION.md rules 1 to 5): final models, 24 pairs, 1200 episodes (50 per pair), stochastic, seed 20000\n")
G = {}
for nm in NAMES:
    d, k, n, fun, rs = episodes(f"{nm}_final.json", PAIRS); rms = J(f"{nm}_final_rms.json")
    assert d["n"] == 1200 and all(n[p] == 50 for p in PAIRS) and fun["p"] == rs.get("success", 0)
    kk = [k[p] for p in PAIRS]; G[nm] = dict(k=kk, tot=sum(kk), fun=fun, rs=rs, rms=rms["identical_before_after"], d=d)
    G[nm]["low"] = [(p, x) for p, x in zip(PAIRS, kk) if x < 10]; G[nm]["learns"] = sum(kk) >= 600 and not G[nm]["low"]
A("### 3.1 Pooled placement (env `is_success`)\n")
A(table(["model", "placed k/1200 (Wilson 95%)", "pairs below 10/50", "VecNormalize obs_rms and ret_rms identical before/after"],
        [[nm, W(G[nm]["tot"], 1200), len(G[nm]["low"]), "yes" if G[nm]["rms"] else "NO"] for nm in NAMES]))
A("### 3.2 Mechanical rule table\n")
rows = []
for nm in NAMES:
    g = G[nm]; fc = []
    if g["tot"] < 600: fc.append(f"pooled {g['tot']} < 600")
    if g["low"]: fc.append(f"{len(g['low'])} pair(s) < 10/50: " + ", ".join(f"{p} {x}/50" for p, x in g["low"]))
    rows.append([nm, f"{g['tot']}/1200", "yes" if g["tot"] >= 600 else "no", len(g["low"]), "yes" if g["learns"] else "no", "; ".join(fc) or "none", "yes" if g["tot"] >= 960 else "no"])
A(table(["model", "pooled", "pooled >= 600", "pairs < 10/50", "Rule 1: learns", "failing conditions", "Rule 5 (reported): pooled >= 960"], rows))
L = {a: sum(G[n]["learns"] for n in NAMES if n[4] == a) for a in "CD"}
A(f"- Rule 2: seeds that learn: C {L['C']} of 2, D {L['D']} of 2.\n- Rule 3: D learns on {L['D']} seeds, C on {L['C']}: " + ("D replaces C." if L["D"] > L["C"] else "C is kept.") + "\n- Rule 4: " + ("triggered." if L["C"] + L["D"] == 0 else "not triggered (at least one seed learns).") + "\n- Rule 5 (reported, not gated): " + ", ".join(f"{n} {'yes' if G[n]['tot'] >= 960 else 'no'}" for n in NAMES) + ".\n")
A("### 3.3 Per pair, placed k/50 [Wilson 95%], preregistration order\n")
A(table(["pair"] + NAMES, [[p] + [f"{G[n]['k'][i]}/50 [{wilson(G[n]['k'][i],50)[0]:.1f}, {wilson(G[n]['k'][i],50)[1]:.1f}]" for n in NAMES] for i, p in enumerate(PAIRS)]))
A("### 3.4 `terminated_reason` counts and funnel\n")
A("Funnel: `grasp_ever` is labelled \"lift over 10 mm (undercounts)\". `held` = both pads on the piece, no piece-board contact. `released` = state S2 reached. `placed` = env `is_success` (equals the `success` count).\n")
A(table(["model", "success", "time_limit", "piece_off_board", "bad_contact", "lift over 10 mm (undercounts)", "held", "released", "placed"],
        [[n, G[n]["rs"].get("success", 0), G[n]["rs"].get("time_limit", 0), G[n]["rs"].get("piece_off_board", 0), G[n]["rs"].get("bad_contact", 0),
          f"{G[n]['fun']['g']}/1200", f"{G[n]['fun']['h']}/1200", f"{G[n]['fun']['r']}/1200", f"{G[n]['fun']['p']}/1200"] for n in NAMES]))

# ---------------- reported
A("## 4. REPORTED results (not gated; none of these enters a rule)\n")
A("### 4.1 Zero-shot (a): 12 pairs on files b and g, never trained, same move type as training. One seed per model.\n")
A("Pairs: " + " ".join(S.NEAR12) + ". 300 episodes, 25 per pair, stochastic, seed 20000.\n")
rows = []
for nm in NAMES:
    d, k, n, fun, rs = episodes(f"zs_near_{nm}.json", S.NEAR12); assert d["n"] == 300 and all(n[p] == 25 for p in S.NEAR12)
    rows.append([nm, W(sum(k.values()), 300), f"{fun['g']}/300", f"{fun['h']}/300", f"{fun['r']}/300", f"{fun['p']}/300"])
A(table(["model", "placed (Wilson 95%)", "lift over 10 mm (undercounts)", "held", "released", "placed"], rows))
A("Per-pair k/25 in `section3_output.txt` (embedded in 4.9).\n")
A("### 4.2 Zero-shot (b): the 20 RS29 pairs. `e4:e5` is a TRAINING pair in RS31; the headline is the 19 untrained pairs.\n")
A("20-pair list (order of `results/rs29_random_squares/PREREGISTRATION.md`): " + ",".join(S.RS29) + ". 300 episodes, 15 per pair, stochastic, seed 20000. `e4:e5` is the only one of the 20 that is among the 24 training pairs (checked by script).\n")
rows19 = []; rows20 = []
for nm in NAMES:
    d, k, n, fun, rs = episodes(f"zs_rs29pairs_{nm}.json", S.RS29); assert d["n"] == 300 and all(n[p] == 15 for p in S.RS29)
    k19 = sum(k[p] for p in S.RS29 if p != "e4:e5")
    rows19.append([nm, W(k19, 285), sum(1 for p in S.RS29 if p != "e4:e5" and k[p]), W(sum(k.values()), 300), f"e4:e5 (training pair) {k['e4:e5']}/15"])
    rows20.append([nm] + [k[p] for p in S.RS29])
A("**Headline: 19 untrained pairs (n = 285)**\n")
A(table(["model", "placed, 19 untrained pairs (Wilson 95%)", "untrained pairs with >= 1 placement", "all 20 pairs (incl. training pair), for reference", "training pair"], rows19))
A("Per pair, k/15 (`e4:e5` marked as training pair):\n")
A(table(["model"] + [p + (" (training pair)" if p == "e4:e5" else "") for p in S.RS29], rows20))
A("### 4.3 Deterministic against stochastic, 24 pairs. REPORTING CHOICE (not in PREREGISTRATION.md): 48 deterministic episodes = 2 per pair, seed 20000\n")
rows = []; notes = []
for nm in NAMES:
    d, k, n, fun, rs = episodes(f"det24_{nm}.json", PAIRS); assert d["n"] == 48 and d["deterministic"] and all(n[p] == 2 for p in PAIRS)
    E, T = d["episodes"], d["traj"]; ones = [p for p in PAIRS if k[p] == 1]
    same_t = sum(T[i] == T[i + 24] for i in range(24)); same_e = sum(E[i] == E[i + 24] for i in range(24))
    kp = sum(k[p] == 2 for p in PAIRS)
    rows.append([nm, W(sum(k.values()), 48) + " (48-episode interval assumes independent episodes, not valid when the two episodes are identical)",
                 W(kp, 24) + " (effective n = 24: pairs with 2 placed / 24)" if not ones else f"pairs with exactly 1 placed: {ones}",
                 W(G[nm]["tot"], 1200) + " (stochastic, Section 3.1)", f"{same_t}/24"])
A(table(["model", "deterministic, 48 episodes", "effective-n = 24 row", "stochastic, 1200 episodes", "pairs whose 2 episodes have identical per-step trajectory records"], rows))
A("Per-pair placed count (0, 1 or 2), funnel and the identity check are in `section3_output.txt` (embedded in 4.9). The per-step records compared are `rel, ap, l, r, board, d, tilt, lift` (from the JSON `traj`); the action sequence itself is not stored in the JSON.\n")
A("### 4.4 Policy std = exp(log_std), 3,000,000 checkpoint (not the final model) and earlier checkpoints\n")
A("Dims: dx, dy, dz, gripper. All values from `rc_*_steps.zip` `policy.pth`. `section3_items45_output.txt` (item 4) has the 500k, 1M, 2M, 3M rows for all four runs. Full series for the two C runs (30 checkpoints and the final model, `section3_std30_output.txt`):\n")
A(block("section3_std30_output.txt"))
A("### 4.5 Monitor: `ever_held` per 10% chunk of training and rolling training placement per 100k steps\n")
A("Chunk edges come from the cumulative episode length (`l`) in each Monitor file. Training placement = Monitor `terminated_reason == success`. D: computed per Monitor file (4 files) and pooled; for D, 100k training steps = 25k steps of each file (deviation n).\n")
A(block("section3_items45_output.txt"))
A("### 4.6 Eval against training cross-check (the same output, section B above)\n")
A("The 10-point flag is a reporting choice, not pre-registered. No gap exceeds 10 points. Interval overlap is computed exactly: of the eight comparisons, only the C seed 0 held comparison (eval 78.2% vs training 85.6%, gap -7.3) has non-overlapping 95% intervals (eval [75.828, 80.492], training [83.335, 87.588]). The C seed 1 placed comparison (gap +7.4) has overlapping intervals (eval [41.380, 46.991], training [32.294, 41.557]).\n")
A("### 4.7 Wrapper equivalence (`rms_wrapper.py` against plain `scripts/eval_probe.py`)\n")
a, b = J("rs31D_seed0_final.json"), J("equiv_plain_rs31D_seed0.json")
A(f"rs31D_seed0, 1200 episodes, same arguments as Section 3.1 above: per-episode records identical in {sum(x == y for x, y in zip(a['episodes'], b['episodes']))}/{len(a['episodes'])}; whole JSON identical: {a == b}. The plain run is `equiv_plain_rs31D_seed0.json`.\n")
A("### 4.8 VecNormalize frozen check (all evaluations)\n")
bad = [e["label"] for e in M3["evals"] if not e["plain_eval_probe"] and not J(Path(e["log"]).with_suffix("").name + "_rms.json")["identical_before_after"]]
A(f"For every wrapper-run evaluation (4 gated, 12 reported) obs_rms and ret_rms (mean, var, count) are identical before and after: failures: {bad or 'none'} (gated: " + ", ".join(f"{n} {'yes' if G[n]['rms'] else 'NO'}" for n in NAMES) + ").\n")
A("### 4.9 Verbatim script outputs\n")
A("`section3_output.txt` (zero-shot, deterministic, wrapper equivalence):\n"); A(block("section3_output.txt"))

# ---------------- deviations
A("## 5. Deviations and disclosures\n")
d = [
 "First launch killed at 02:09:43 on 2026-10-06 by a WSL distro shutdown (trigger unknown). All four runs restarted from step 0 at 12:39:40 on SHA ac84418 with identical configs. The partial first-launch output is in `runs/_died_20261006__probe_cart_rs31{C_seed0,C_seed1,D_seed0}` plus `_train.log` files and is not evaluated.",
 "Env seed streams overlap: SB3 seeds env i with seed+i (`VecEnv.seed`). C seed0 uses env seed 0, C seed1 env seed 1, D seed0 env seeds 0 to 3, D seed1 env seeds 1 to 4.",
 "Run end steps: C 3,000,320 (1465 rollouts of 2048), D 3,006,464 (367 rollouts of 8192). Gated evaluation uses the final model. Training diagnostics use the 3,000,000 checkpoint.",
 "D writes four Monitor files (`monitor_0` to `monitor_3`); C writes one.",
 "D arm is a bundle (n_envs 4 plus linear LR decay to 0), so a D versus C difference cannot be attributed to either factor alone.",
 "Reporting choices where the preregistration is silent: 48 deterministic episodes, chunking by cumulative episode length, 3,000,000 checkpoint for std.",
 "Check start time for the runs/ modification check: 2026-10-06 17:24:49 SAST.",
 "`rms_wrapper.py` runs `scripts/eval_probe.py` unmodified through `runpy` and records `ret_rms` as well as `obs_rms` (mean, var, count) before and after each evaluation. It was added because `eval_probe.py` records only the `obs_rms` before/after flag and that file may not be edited. The equivalence with plain `eval_probe.py` is in 4.7.",
 "Rule 3 outcome is a mechanical decision rule. D bundles n_envs 4 and linear LR decay, so the result cannot be attributed to either factor. Two seeds per arm. C seed 1 scored 530/1200 against the fixed 600 threshold.",
 "Funnel columns: `grasp_ever` means lift over 10 mm (it undercounts). `lifted_30mm` and `carried_within_3cm` are unreliable per RS30 (they read 0 even for a 99.3% policy) and are not used; they remain in the result JSONs only.",
 "Zero-shot (a): 12 pairs on files b and g, never trained, same move type as training. One seed per model.",
 "Zero-shot (b) headline = the 19 untrained pairs (n = 285 per model); `e4:e5` is a training pair.",
 "Deterministic effective-n: in all four models every pair has 0 or 2 placed episodes and the two episodes of each pair have identical per-step trajectory records (24/24 pairs, computed in `section3_output.txt`). The 48-episode interval assumes independent episodes and is not valid when the two episodes are identical; the effective-n = 24 row (pairs with 2 placed / 24) is reported beside it.",
 "Training placement per 100k for D is pooled over the four Monitor files with 100k training steps = 25k file steps each. Training placement is the Monitor `terminated_reason == success` (the Monitor has no separate placement column).",
 "C seed 0 gripper std (exp(log_std)) rose from 0.9515 at the 100k checkpoint to 66.0003 at the 3,000,000 checkpoint (65.8444 in the final model); it is above 1.0 from the 500k checkpoint on. The series is not monotone: it decreases at 100k to 200k and 300k to 400k, and the final model is below the 3,000,000 checkpoint (table in 4.4). Reported without a causal claim.",
 "No positive control was run in RS31. The RS30 control (D29 squash seed 3, e4:e5, 298/300) used plain `scripts/eval_probe.py`, not `rms_wrapper.py`; the wrapper was compared directly instead (4.7).",
 "Cross-check B: the 10-point flag is a reporting choice, not pre-registered. Only the C seed 0 held comparison (gap -7.3) has non-overlapping 95% intervals (4.6). The C seed 1 placed gap (+7.4) has overlapping intervals (eval lower bound 41.380, training upper bound 41.557).",
]
for i, t in enumerate(d): A(f"{'abcdefghijklmnopq'[i]}. {t}")
A("\n## 6. Files and regeneration (all under this directory; nothing under `runs/` is written)\n")
A("Order: `run_evals.py start/models/end` (Section 2, writes `EVAL_MANIFEST.json`), `section2_table.py > section2_output.txt`, `run_section3.py` (writes `EVAL_MANIFEST_section3.json`), `section3_table.py > section3_output.txt`, `section3_items45.py > section3_items45_output.txt`, `section3_std30.py > section3_std30_output.txt`, `make_readme.py` (this file). `rms_wrapper.py` is the wrapper used by both runners. Raw outputs: `{rs31C,rs31D}_seed{0,1}_final.json`, `zs_near_*.json`, `zs_rs29pairs_*.json`, `det24_*.json`, `equiv_plain_rs31D_seed0.json`, with `.log` and `_rms.json` beside each.\n")
A("`section2_output.txt` (gated, verbatim):\n"); A(block("section2_output.txt"))
(EV / "README.md").write_text("\n".join(out))
print("wrote README.md", len("\n".join(out).splitlines()), "lines")
